def _build_model(self, model: str | list[str] | tuple[str, ...]) -> lmfit.Model:
    if isinstance(model, (list, tuple)):
        return self._build_composite_model(list(model))
    if isinstance(model, str):
        return self._get_model_cls(model)()
    raise ValueError(f"Unknown model {model}")

def _build_composite_model(self, model_list: Sequence[str]) -> lmfit.Model:
    if not model_list:
        raise ValueError("Composite model list cannot be empty.")

    self.model_name_sequence = list(model_list)
    # A unique component name and prefix per entry (e.g. "GaussianModel_0").
    self.model_sequence = [f"{name}_{index}" for index, name in enumerate(model_list)]
    self.model_prefixes = {name: f"{name}_" for name in self.model_sequence}
    self.model_components = {
        component_name: self._get_model_cls(model_name)(prefix=f"{component_name}_")
        for model_name, component_name in zip(model_list, self.model_sequence)
    }

    composite_model: lmfit.model.Model | None = None
    for component in self.model_components.values():
        composite_model = component if composite_model is None else composite_model + component

    # Allow lookups by model name only when the names are unambiguous.
    if len(set(model_list)) == len(model_list):
        self.model_name_to_component = dict(zip(model_list, self.model_sequence))
    else:
        self.model_name_to_component = None

    logger.debug(
        f"Initialized composite lmfit model with components={list(self.model_components.keys())} "
        f"prefixes={self.model_prefixes}"
    )
    return composite_model

@staticmethod
def _get_model_cls(model_name: str):
    model_cls = getattr(lmfit.models, model_name, None)
    if not model_cls:
        raise ValueError(f"Unknown model {model_name}")
    return model_cls
